ee:message.ee:set-payload:
%dw 2.0
output application/xml
---
"soapenv:Envelope" @(
    "xmlns:soapenv":"http://schemas.xmlsoap.org/soap/envelope/",
    "xmlns:mdm":"http://www.etb.com.co/Gateway/MDM_Data_Services"
): {
    "soapenv:Header": null,
    "soapenv:Body": {
        "mdm:Get_Customer": {
            "mdm:WSRequestHeader": {
                "mdm:system": {
                    "mdm:name": vars.headers.name default "Salesforce",
                    "mdm:correlationId": vars.headers."x-correlation-id" default correlationId,
                    "mdm:processingServer": "MDM"
                }
            },
            "mdm:WSRequestBody": {
                "mdm:id": vars.queryParams.idCuenta,
                "mdm:document_type": vars.queryParams.tipoDocumento,
                "mdm:document_number": vars.queryParams.numeroDocumento,
                "mdm:id_origin_system": null
            }
        }
    }
}
